CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "agent_wakeup_requests_execution_reconciliation_delivery_uq" ON "agent_wakeup_requests" USING btree ("company_id","idempotency_key") WHERE "agent_wakeup_requests"."idempotency_key" LIKE 'execution-reconciliation:%' AND "agent_wakeup_requests"."status" NOT IN ('skipped', 'failed', 'cancelled');--> statement-breakpoint
CREATE INDEX CONCURRENTLY IF NOT EXISTS "issue_recovery_actions_continuation_wait_due_idx" ON "issue_recovery_actions" USING btree (("evidence"#>>'{continuationWait,recheckAt}'),"id") WHERE "issue_recovery_actions"."status" = 'resolved' and "issue_recovery_actions"."evidence"->>'continuationDelivery' = 'waiting';